content_blocks.code:
LIN_description_file;                    # LDF头部
LIN_protocol_version = "2.1";           # 协议版本
LIN_speed = 19.2 kbps;                  # 波特率

Nodes {
    Master: BCM, 5 ms, 0.1 ms;          # 主机、时基
    Slaves: Window_L, Window_R;          # 从机列表
}

Signals {
    WindowCmd: 2, 0, BCM, Window_L;     # 信号名, 长度(bit), 初始值, 发布者, 接收者
    WindowPos: 8, 0, Window_L, BCM;     # 位置反馈
}

Frames {
    WindowCtrl: 1, BCM, 1 {              # 帧名, ID, 发布节点, 帧长(字节)
        WindowCmd, 0;                    # 携带的信号, 起始位
    }
    WindowStatus: 2, Window_L, 1 {
        WindowPos, 0;
    }
}
